content:
Task: Make the catalogue's heading and each book's availability match the spec wording. (Paging is a separate task: keep listing every book.)

Spec excerpt (SPEC.md):
BRW-1: The page at `/` has the main heading "Library catalogue" and shows the books six at a time, each with its title, its author, its genre, its year and "Available" or "On loan"; each title is a link to the book's page at `/books/<id>`.

File features/browse/pages/BrowsePage.tsx:
```tsx
// @line-base pages/ListPage
// @line-route /
import Link from 'next/link';
import { ListPage } from '../../../library/pages/ListPage';
import books from '../../../library/fixtures/books.json';

type Book = { id: string; title: string; author: string; genre: string; year: number; pages: number; available: boolean };

export function BrowsePage() {
  const items = books as Book[];
  return (
    <ListPage title="Books" empty={<p>No books yet.</p>}>
      {items.length > 0 && items.map((item) => (
        <article key={item.id} className="flex flex-col gap-2 rounded-lg border border-slate-200 p-4 shadow-sm">
          <h2 className="text-lg font-semibold"><Link href={`/books/${item.id}`}>{item.title}</Link></h2>
          <p>{item.author}</p>
          <p>{item.genre}</p>
          <p>{String(item.year)}</p>
          <p>{String(item.pages)}</p>
          <p>{String(item.available)}</p>
        </article>
      ))}
    </ListPage>
  );
}
```

